// -----------------------------------------------------------------------------
// TestBohrisData.cs
// -----------------------------------------------------------------------------
// This file contains unit tests for the Bohris data access layer. It verifies
// that field metadata can be listed, that drilling data can be retrieved,
// that measurement values, water level data, and dependent data are correctly
// fetched, and that case‑insensitive field access and language‑specific fields
// behave as expected.
// -----------------------------------------------------------------------------
using Bovis.Interfaces;
using Bovis.Interfaces.Configuration;
using Bovis.TestProfile;
using DbTools.DbUrl;
namespace Bovis.Data.Bohris.Test
{
    /// <summary>
    /// Tests for retrieving field information (metadata) from the Bohris schema.
    /// </summary>
    [TestClass]
    public class TestBohrisFieldInfo : TestClassCommon
    {
        /// <summary>
        /// Lists all field help entries for the table <c>T_STAMMDATEN</c> and writes
        /// them to the test context output. This verifies that the <c>FieldInfos</c>
        /// helper can enumerate column metadata correctly.
        /// </summary>
        [TestMethod]
        public void ListFields()
        {
            var infos=Bovis.Data.FieldInfos.LoadFieldInfos("Bovis.Data.Bohris/columnhelp.json");
            foreach (var key in infos.GetHelp("T_STAMMDATEN"))
            {
                TestContext.WriteLine($"{key.TABLE_NAME},{key.COLUMN_NAME},{key.COMMENTS}");
            }
        }
    }

    /// <summary>
    /// Integration tests for the <c>BohrisDataSource</c> class, covering retrieval of
    /// drilling records, measurement data, water level data, dependent data, and
    /// case‑insensitive field handling.
    /// </summary>
    [TestClass]
    public class TestBohrisData
    {
        // Configuration store used for the in‑memory test database.
        readonly IConfigurationStore m_configDb = Storage.Storage.OpenStorageFile(":memory:");

        /// <summary>
        /// Retrieves a drilling record via the external Bohris interface and validates
        /// several key fields and layer information.
        /// </summary>
        [TestMethod]
        public async Task RetrieveExternalInterface()
        {
            var url = new ConnectionUrl(Config.BohrIsUrl);
            using var conn = new BohrisDataSource(url, m_configDb);
            await conn.OpenAsync();
            var item = await conn.FindBohrungAsync((DbKeyValue)12);
            Assert.AreEqual("GE", item.GetValue("ARFACH"));
            Assert.AreEqual(16, item.SchichtInfos.Count);
            Assert.AreEqual("mS", item.SchichtInfos[0].GetValue("PETH"));
            Assert.AreEqual("fS-mS", item.SchichtInfos[3].GetValue("PETH"));
        }

        /// <summary>
        /// Retrieves measurement data for a specific drilling record and verifies
        /// the count, depth, and value of selected measurement items.
        /// </summary>
        [TestMethod]
        public async Task TestMesswerte()
        {
            var url = new ConnectionUrl(Config.BohrIsUrl);
            using var conn = new BohrisDataSource(url, m_configDb);
            await conn.OpenAsync();
            var delta = 0.0001;
